// Assume TreeNode is defined as follows:
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    int height;
};

void avlInsert(TreeNode*& root, const int& item) {
    // Helper lambda to get the height of a node
    auto height = [](TreeNode* node) -> int {
        return node ? node->height : 0;
    };

    // Helper lambda to update the height of a node
    auto updateHeight = [&height](TreeNode* node) {
        if (node) {
            node->height = 1 + std::max(height(node->left), height(node->right));
        }
    };

    // Helper lambda to get the balance factor of a node
    auto balanceFactor = [&height](TreeNode* node) -> int {
        return node ? height(node->left) - height(node->right) : 0;
    };

    // Helper lambda for right rotation
    auto rightRotate = [](TreeNode*& y) -> TreeNode* {
        TreeNode* x = y->left;
        TreeNode* T2 = x->right;

        x->right = y;
        y->left = T2;

        updateHeight(y);
        updateHeight(x);

        return x;
    };

    // Helper lambda for left rotation
    auto leftRotate = [](TreeNode*& x) -> TreeNode* {
        TreeNode* y = x->right;
        TreeNode* T2 = y->left;

        y->left = x;
        x->right = T2;

        updateHeight(x);
        updateHeight(y);

        return y;
    };

    // Standard BST insertion
    if (!root) {
        root = new TreeNode{item, nullptr, nullptr, 1};
        return;
    }

    if (item < root->val) {
        avlInsert(root->left, item);
    } else if (item > root->val) {
        avlInsert(root->right, item);
    } else {
        return; // Duplicates not allowed
    }

    // Update height of the current node
    updateHeight(root);

    // Get the balance factor
    int balance = balanceFactor(root);

    // Left Left Case
    if (balance > 1 && item < root->left->val) {
        root = rightRotate(root);
        return;
    }

    // Right Right Case
    if (balance < -1 && item > root->right->val) {
        root = leftRotate(root);
        return;
    }

    // Left Right Case
    if (balance > 1 && item > root->left->val) {
        root->left = leftRotate(root->left);
        root = rightRotate(root);
        return;
    }

    // Right Left Case
    if (balance < -1 && item < root->right->val) {
        root->right = rightRotate(root->right);
        root = leftRotate(root);
        return;
    }
}

